void bn_copy(bn_t c, const bn_t a) { /* <=== bn_copy */ 
	if (c->dp == a->dp) {
		return;
	}

	bn_grow(c, a->used);
	dv_copy(c->dp, a->dp, a->used);

	c->used = a->used;
	c->sign = a->sign;
}

void bn_read_bin(bn_t a, const uint8_t *bin, int len) { /* <=== bn_read_bin */ 
	int i, j;
	dig_t d = (RLC_DIG / 8);
	int digs = (len % d == 0 ? len / d : len / d + 1);

	bn_grow(a, digs);
	bn_zero(a);
	a->used = digs;

	for (i = 0; i < digs - 1; i++) {
		d = 0;
		for (j = (RLC_DIG / 8) - 1; j >= 0; j--) {
			d = d << 8;
			d |= bin[len - 1 - (i * (RLC_DIG / 8) + j)];
		}
		a->dp[i] = d;
	}
	d = 0;
	for (j = (RLC_DIG / 8) - 1; j >= 0; j--) {
		if ((int)(i * (RLC_DIG / 8) + j) < len) {
			d = d << 8;
			d |= bin[len - 1 - (i * (RLC_DIG / 8) + j)];
		}
	}
	a->dp[i] = d;

	a->sign = RLC_POS;
	bn_trim(a);
}

void bn_write_bin(uint8_t *bin, int len, const bn_t a) { /* <=== bn_write_bin */ 
	int size, k;
	dig_t d;

	size = bn_size_bin(a);

	if (len < size) {
		RLC_THROW(ERR_NO_BUFFER);
	}

	k = 0;
	for (int i = 0; i < a->used - 1; i++) {
		d = a->dp[i];
		for (int j = 0; j < (int)(RLC_DIG / 8); j++) {
			bin[len - 1 - k++] = d & 0xFF;
			d = d >> 8;
		}
	}

	d = a->dp[a->used - 1];
	while (d != 0) {
		bin[len - 1 - k++] = d & 0xFF;
		d = d >> 8;
	}

	while (k < len) {
		bin[len - 1 - k++] = 0;
	}
}

void bn_mod_2b(bn_t c, const bn_t a, int b) { /* <=== bn_mod_2b */ 
	int i, first, d;

	if (b <= 0) {
		bn_zero(c);
		return;
	}

	if (b >= (int)(a->used * RLC_DIG)) {
		bn_copy(c, a);
		return;
	}

	bn_copy(c, a);

	RLC_RIP(b, d, b);

	first = (d) + (b == 0 ? 0 : 1);
	for (i = first; i < c->used; i++)
		c->dp[i] = 0;

	c->dp[d] &= RLC_MASK(b);

	bn_trim(c);
}

int bn_get_bit(const bn_t a, int bit) { /* <=== bn_get_bit */ 
	int d;

	RLC_RIP(bit, d, bit);

	if (d >= a->used) {
		return 0;
	} else {
		return (a->dp[d] >> bit) & (dig_t)1;
	}
}

int bn_is_zero(const bn_t a) { /* <=== bn_is_zero */ 
	if (a->used == 0) {
		return 1;
	}
	if ((a->used == 1) && (a->dp[0] == 0)) {
		return 1;
	}
	return 0;
}

void bn_zero(bn_t a) { /* <=== bn_zero */ 
	a->sign = RLC_POS;
	a->used = 1;
	dv_zero(a->dp, a->alloc);
}

int bn_size_bin(const bn_t a) { /* <=== bn_size_bin */ 
	dig_t d;
	int digits;

	digits = (a->used - 1) * (RLC_DIG / 8);
	d = a->dp[a->used - 1];

	while (d != 0) {
		d = d >> 8;
		digits++;
	}
	return digits;
}

void bn_set_bit(bn_t a, int bit, int value) { /* <=== bn_set_bit */ 
	int d;

	RLC_RIP(bit, d, bit);

	if (value == 1) {
		a->dp[d] |= ((dig_t)1 << bit);
		if ((d + 1) > a->used) {
			a->used = d + 1;
		}
	} else {
		a->dp[d] &= ~((dig_t)1 << bit);
		bn_trim(a);
	}
}

void md_mgf(uint8_t *key, int key_len, const uint8_t *in, /* <=== md_mgf */ 
		int in_len) {
	uint32_t i, j, d;
	uint8_t *buffer = RLC_ALLOCA(uint8_t, in_len + sizeof(uint32_t));
	uint8_t *t = RLC_ALLOCA(uint8_t, key_len + RLC_MD_LEN);

	if (buffer == NULL || t == NULL) {
		RLC_FREE(buffer);
		RLC_FREE(t);
		RLC_THROW(ERR_NO_MEMORY);
	}

	/* d = ceil(kLen/hLen). */
	d = RLC_CEIL(key_len, RLC_MD_LEN);
	memcpy(buffer, in, in_len);
	for (i = 0; i < d; i++) {
		j = util_conv_big(i);
		/* c = integer_to_string(c, 4). */
		memcpy(buffer + in_len, &j, sizeof(uint32_t));
		/* t = t || hash(z || c). */
		md_map(t + i * RLC_MD_LEN, buffer, in_len + sizeof(uint32_t));
	}
	memcpy(key, t, key_len);

	RLC_FREE(buffer);
	RLC_FREE(t);
}

void bn_rsh(bn_t c, const bn_t a, int bits) { /* <=== bn_rsh */ 
	int digits = 0;

	if (bits <= 0) {
		bn_copy(c, a);
		return;
	}

	RLC_RIP(bits, digits, bits);

	if (digits > 0) {
		bn_rshd_low(c->dp, a->dp, a->used, digits);
	}
	c->used = a->used - digits;
	c->sign = a->sign;

	if (c->used > 0 && bits > 0) {
		if (digits == 0 && c != a) {
			bn_rshb_low(c->dp, a->dp + digits, a->used - digits, bits);
		} else {
			bn_rshb_low(c->dp, c->dp, c->used, bits);
		}
	}
	bn_trim(c);
}

static uint8_t *hash_id(int md, int *len) { /* <=== hash_id */ 
	switch (md) {
		case SH224:
			*len = sizeof(sh224_id);
			return (uint8_t *)sh224_id;
		case SH256:
			*len = sizeof(sh256_id);
			return (uint8_t *)sh256_id;
		case SH384:
			*len = sizeof(sh384_id);
			return (uint8_t *)sh384_id;
		case SH512:
			*len = sizeof(sh512_id);
			return (uint8_t *)sh512_id;
		default:
			RLC_THROW(ERR_NO_VALID);
			return NULL;
	}
}

